// Verus implementation for the cookie‐distribution problem

verus! {

    // Returns true iff we can serve 'n' regular guests (1 cookie each, from either pile)
    // and 'm' special guests (1 cookie from each pile, i.e. 2 cookies total each),
    // given piles of sizes `a` and `b`.
    //
    // Specification:
    //   - We require that the total number of guests is positive (n + m > 0).
    //   - We ensure that `result` is true exactly when
    //       1) each pile has at least `m` cookies, and
    //       2) the total cookies across both piles is ≥ (n + 2*m).
    //
    // Implementation note:
    //   To avoid any u8‐overflow when checking a + b ≥ n + 2m, we first
    //   subtract m from each pile (after checking a ≥ m and b ≥ m), then
    //   check that the remaining cookies are enough for the n regular guests.

    pub fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool
        requires n as nat + m as nat > 0
        ensures  result ==
            (  a as nat >= m as nat
            && b as nat >= m as nat
            && a as nat + b as nat >= n as nat + 2 * m as nat
            )
    {
        // First ensure each pile can supply the m “special‐guest” cookies.
        if a < m || b < m {
            return false;
        }
        // If each pile has at least m, subtract m from each and see if
        // the remaining (a – m) + (b – m) cookies suffice for n regular guests.
        let free: u8 = (a - m) + (b - m);
        free >= n
    }

} // end of verus! block